 function speech(x){x=cl(x);if(!x)return '';var p=x.split(/\s+[—–]\s+/);if(p.length>1){var k=[p[0]];for(var i=2;i<p.length;i+=2)k.push(p[i]);x=k.map(function(t,j){t=t.trim().replace(/[\s,;:]+$/,'');return j<k.length-1&&!/[.!?…]$/.test(t)?t+'.':t;}).join(' ');}
  x=x.replace(/^[«"„]|[»"“]$/g,'').replace(/[\s,;:—–-]+$/,'').trim();if(x.length>70){var m=x.slice(0,72).match(/^[\s\S]*[.!?…](?=\s|$)/);x=m?m[0]:'';}return x.length>=2?x:'';}
